UPDATE articulos a SET contenido=(SELECT string_agg(coalesce(v.texto,substring(a.contenido from v.inicio for v.largo)),'' ORDER BY v.orden) FROM (VALUES (0, 1, 573, NULL::text),(1,0,0,E'<thead><tr><th rowspan="2" scope="col">Capacitación en materia de:</th><th colspan="2" scope="col">Auto-tanque</th><th colspan="2" scope="col">Vehículo de Reparto</th></tr></thead>'),(2, 574, 7, NULL::text),(3, 674, 2430, NULL::text)) v(orden,inicio,largo,texto)) WHERE a.id='926543d6-c2b8-5802-b418-7fb337280ae6' AND md5(a.contenido)='675eb79c702ef022197426d0aeda8fb7' RETURNING a.id,md5(a.contenido) hash;